<script lang="ts">
  import {summarizeGlobalTasks,type GlobalTaskGroups,type GlobalTaskGroup} from '../lib/globalTaskView.ts';
  import {formatOwnerLocalTime} from '../lib/ownerTime.ts';
  import TaskTitleTrigger from './TaskTitleTrigger.svelte';
  import {taskDisplayName,taskHasCanonicalResult,taskStatusIcon,taskStatusLabel} from '../lib/taskPresentation.ts';
  export let groups:GlobalTaskGroups={inProgress:[],waitingOwner:[],needsAction:[],recentCompleted:[]};
  export let legacyTaskCount=0;
  export let onSelectTask:(taskId:string)=>void=()=>{};
  export let onOpenWorkspace:()=>void=()=>{};
  export let onOpenPrWorkspace:()=>void=()=>{};
  export let selectedTaskId:string|null=null;
  export let onCopyTaskResult:(task:any)=>void=()=>{};
  export let center=false;
  export let navigationOnly=false;
  type Filter='ALL'|'RUNNING'|'WAITING_OWNER'|'COMPLETED'|'FAILED'|'UNMAPPED';
  let filter:Filter='ALL';
  const definitions:{key:GlobalTaskGroup;label:string}[]=[{key:'inProgress',label:'进行中'},{key:'waitingOwner',label:'等待 Owner'},{key:'needsAction',label:'需要处理'},{key:'recentCompleted',label:'最近完成'}];
  $: tasks=definitions.flatMap(definition=>groups[definition.key]).sort((left,right)=>Date.parse(right.createdAt??'')-Date.parse(left.createdAt??''));
  $: filtered=tasks.filter(item=>filter==='ALL'||(filter==='RUNNING'&&item.group==='inProgress')||(filter==='WAITING_OWNER'&&item.group==='waitingOwner')||(filter==='COMPLETED'&&item.group==='recentCompleted')||(filter==='FAILED'&&item.group==='needsAction')||(filter==='UNMAPPED'&&item.scope==='GLOBAL_TASK'));
  $: summary=summarizeGlobalTasks(groups);
  $: taskCount=summary.all;
  $: stats=[['All Tasks',summary.all,'ALL'],['Running',summary.running,'RUNNING'],['Waiting Owner',summary.waitingOwner,'WAITING_OWNER'],['Completed',summary.completed,'COMPLETED'],['Failed',summary.failed,'FAILED'],['Global',summary.global,'UNMAPPED']] as [string,number,Filter][];
</script>
<section class:global-task-center={center} class="global-task-view" data-testid="global-task-view">
  {#if navigationOnly}<div class="global-navigation-entries"><button class="global-task-nav-entry" data-testid="global-task-nav-entry" onclick={onOpenWorkspace}><span><span class="kicker">GLOBAL TASKS</span><strong>全局任务</strong></span>{#if taskCount}<small>{taskCount}</small>{/if}</button><button class="global-task-nav-entry global-pr-nav-entry" data-testid="global-pr-nav-entry" onclick={onOpenPrWorkspace}><span><span class="kicker">GLOBAL PR</span><strong>全局 PR#</strong></span></button></div>{:else}<section class="global-task-workspace" data-testid="global-task-workspace"><div class="section-label"><span>全局任务</span><small>{taskCount} canonical tasks{#if legacyTaskCount} · {legacyTaskCount} legacy excluded{/if}</small></div><div class="task-statistics">{#each stats as stat}<button class:active={filter===stat[2]} onclick={()=>filter=stat[2]}><strong>{stat[1]}</strong><span>{stat[0]}</span></button>{/each}</div><div class="global-task-filters" role="tablist" aria-label="Task filters">{#each stats as stat}<button class:active={filter===stat[2]} onclick={()=>filter=stat[2]}>{stat[0]}</button>{/each}</div><div class="global-task-table" data-testid="global-task-list"><div class="global-task-row global-task-heading"><span>任务名称</span><span>状态</span><span>结果</span><span>Entity / WP</span><span>PR binding</span><span>Branch</span><span>Run ID</span><span>Created time</span><span>Completed time</span><span>Source</span></div>{#each filtered as item}{@const task=item.task}{@const status=String(task?.status??item.state??'READY').toUpperCase()}<div class:selected={selectedTaskId===item.canonicalTaskId} class="global-task-row" data-testid={`global-task-${item.id}`}><TaskTitleTrigger taskId={item.canonicalTaskId} label={task?taskDisplayName(task):item.id} selected={selectedTaskId===item.canonicalTaskId} onSelect={onSelectTask}/><span class="global-task-status" title={taskStatusLabel(status)} aria-label={taskStatusLabel(status)}>{taskStatusIcon(status)}</span>{#if task&&taskHasCanonicalResult(task)}<button class="global-task-result" title="复制运行结果" aria-label="复制运行结果" onclick={()=>onCopyTaskResult(task)}>📋</button>{:else}<span class="global-task-result unavailable" title="暂无运行结果" aria-label="暂无运行结果">🈚</span>{/if}<span>{item.entity?.id??'GLOBAL / UNMAPPED'}</span><span>{item.prBinding??'—'}</span><span>{item.branch??'UNKNOWN'}</span><span>{item.runId??'NOT_STARTED'}</span><span>{formatOwnerLocalTime(item.createdAt)}</span><span>{formatOwnerLocalTime(item.completedAt)}</span><span>{task?.origin??'UNKNOWN'}</span></div>{:else}<p class="global-task-empty">暂无符合条件的任务。</p>{/each}</div></section>{/if}
</section>
<style>
  .global-task-view{}
  .global-navigation-entries{display:grid;gap:1px}.global-pr-nav-entry{border-top:1px solid var(--border-soft)}
  .global-task-nav-entry{display:flex;width:100%;align-items:center;justify-content:space-between;padding:10px 12px;border:0;background:transparent;color:var(--text-1);text-align:left;cursor:pointer}.global-task-nav-entry>span{display:grid;gap:2px}.global-task-nav-entry strong{font:600 14px/1.3 var(--font-ui)}.global-task-nav-entry>small{color:var(--text-3);font:500 11px var(--font-tech)}
  .global-task-empty{margin:0;padding:5px 0;color:var(--text-3);font-size:11px}.global-task-workspace{display:grid;gap:14px}.task-statistics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px}.task-statistics button{display:grid;gap:3px;padding:10px;border:1px solid var(--border);border-radius:8px;background:var(--surface);color:var(--text-2);text-align:left;cursor:pointer}.task-statistics button.active,.global-task-filters button.active{border-color:var(--accent);color:var(--accent);background:var(--surface-2)}.task-statistics strong{font:700 18px var(--font-tech);color:var(--text-1)}.task-statistics span{font-size:10px}.global-task-filters{display:flex;flex-wrap:wrap;gap:6px}.global-task-filters button{border:1px solid var(--border);border-radius:999px;background:var(--surface);color:var(--text-2);padding:5px 9px;font-size:11px;cursor:pointer}.global-task-table{overflow:auto;border:1px solid var(--border-soft);border-radius:8px}.global-task-row{display:grid;grid-template-columns:minmax(150px,1.4fr) 48px 48px minmax(130px,1.2fr) 100px minmax(130px,1fr) 110px 150px 150px 90px;gap:10px;align-items:center;width:100%;padding:7px 10px;border:0;border-bottom:1px solid var(--border-soft);background:var(--surface);color:var(--text-1);text-align:left;font-size:11px}.global-task-row:hover{background:var(--surface-2)}.global-task-row.selected{box-shadow:inset 2px 0 var(--accent);background:var(--surface-2)}.global-task-row span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.global-task-heading{position:sticky;top:0;background:var(--surface-2);color:var(--text-3);font-size:10px}.global-task-heading:hover{background:var(--surface-2)}.global-task-status,.global-task-result{display:grid;place-items:center;min-width:0;border:0;background:transparent;color:inherit;text-align:center;font-size:15px}.global-task-result{width:30px;height:26px;cursor:pointer}.global-task-result.unavailable{cursor:default;filter:grayscale(1);opacity:.65}@media (max-width:900px){.task-statistics{grid-template-columns:repeat(3,minmax(0,1fr))}}
</style>
